#!/usr/bin/env node
// Generates the typed models and one method per operation of the Go SDK from ../openapi.json
// (the live spec, https://api.pitchmentor.net/v1/openapi.json). Hand-written transport (retries, errors,
// pagination, webhooks) lives next to the generated file. Run: scripts/regen.sh (download + generate)
// or node codegen/generate.mjs (generate from the committed openapi.json).
import { readFileSync, writeFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const spec = JSON.parse(readFileSync(join(root, "openapi.json"), "utf8"));
// `ErrorResponse` is modelled by each SDK's hand-written error class
const { ErrorResponse: _errorSchema, ...schemas } = spec.components.schemas;

// ── IR ────────────────────────────────────────────────────

const refName = (ref) => ref.split("/").pop();
const isList = (s) => s?.type === "object" && s.properties?.data?.type === "array" && "next_cursor" in (s.properties ?? {});
const listItem = (s) => s.properties.data.items;

const ops = [];
for (const [path, methods] of Object.entries(spec.paths)) {
  for (const [method, op] of Object.entries(methods)) {
    const params = op.parameters ?? [];
    const ok = Object.entries(op.responses).find(([code]) => code.startsWith("2"))[1];
    const query = params.filter((p) => p.in === "query");
    ops.push({
      id: op.operationId,
      method: method.toUpperCase(),
      path,
      tag: op.tags?.[0] ?? "",
      summary: op.summary ?? "",
      description: op.description ?? "",
      scope: op["x-required-scope"] ?? null,
      pathParams: params.filter((p) => p.in === "path").map((p) => p.name),
      query,
      body: op.requestBody?.content?.["application/json"]?.schema ?? null,
      response: ok.content?.["application/json"]?.schema ?? null,
      csv: !!ok.content?.["text/csv"],
      paginated: query.some((p) => p.name === "cursor"),
      destructive: op["x-destructive"] === true, // flagged in docs, CLI (--yes) and MCP (destructiveHint)
    });
  }
}
// Events an endpoint can subscribe to (webhook.test is in `webhooks` but is only sent by testWebhookEndpoint)
const subscribableEvents = schemas.WebhookEndpoint.properties.events.items.enum;
const webhookEvents = Object.values(spec.webhooks ?? {}).map((w) => {
  const s = w.post.requestBody.content["application/json"].schema;
  return { type: s.properties.type.const, data: s.properties.data };
});

// ── naming ────────────────────────────────────────────────

const upper = (s) => s[0].toUpperCase() + s.slice(1);
const snake = (s) => s.replace(/([a-z0-9])([A-Z])/g, "$1_$2").replace(/-/g, "_").toLowerCase();
const goName = (s) =>
  s
    .split(/[_-]/)
    .map(upper)
    .join("")
    .replace(/Id(?=[A-Z]|$)/g, "ID")
    .replace(/Url(?=[A-Z]|$)/g, "URL");
const docLines = (op) =>
  [
    op.summary + (op.summary.endsWith(".") ? "" : "."),
    op.description.replace(/\n*Requires scope `[^`]+`\.$/, "").trim(),
    op.scope ? `Requires scope \`${op.scope}\`.` : "",
    op.destructive ? "DESTRUCTIVE: cannot be undone." : "",
  ].filter(Boolean);
const types = (s) => [s.type].flat().filter(Boolean);
const nullable = (s) => types(s).includes("null");
const HEADER = "Code generated by codegen/generate.mjs from openapi.json. DO NOT EDIT.";

// ── Go ────────────────────────────────────────────────────

function genGo() {
  const goDoc = (s) => {
    const enumValues = s.enum ?? s.items?.enum;
    const text = [s.description, enumValues && `One of: ${enumValues.join(", ")}.`].filter(Boolean).join(" ");
    return text ? `\t// ${text}\n` : "";
  };
  const structs = [];

  // ptr: wrap scalars in a pointer (nullable or optional)
  function goType(s, hint, ptr = false) {
    if (!s || Object.keys(s).filter((k) => k !== "description").length === 0) return "json.RawMessage";
    if (s.$ref) return (ptr ? "*" : "") + refName(s.$ref);
    if (s.allOf) return "map[string]any";
    const t = types(s).filter((x) => x !== "null");
    const p = ptr || nullable(s) ? "*" : "";
    switch (t[0]) {
      case "string":
        return p + (s.format === "date-time" ? "time.Time" : "string");
      case "integer":
        return p + "int";
      case "number":
        return p + "float64";
      case "boolean":
        return p + "bool";
      case "array":
        return `[]${goType(s.items, hint + "Item")}`;
      case "object":
        if (isList(s)) return `${p}Page[${goType(listItem(s), hint)}]`;
        if (!s.properties) return "map[string]any";
        goStruct(hint, s);
        return p + hint;
    }
    return "json.RawMessage";
  }

  function goStruct(name, s, embed) {
    const req = new Set(s.required ?? []);
    const fields = Object.entries(s.properties).map(([k, v]) => {
      const optional = !req.has(k);
      const t = goType(v, name + goName(k), optional);
      const omit = optional ? ",omitempty" : "";
      const doc = goDoc(v);
      return `${doc}\t${goName(k)} ${t} \`json:"${k}${omit}"\``;
    });
    structs.push(`type ${name} struct {\n${embed ? `\t${embed}\n` : ""}${fields.join("\n")}\n}\n`);
  }

  for (const [name, s] of Object.entries(schemas)) {
    if (s.allOf) goStruct(name, s.allOf[1], refName(s.allOf[0].$ref));
    else goStruct(name, s);
  }
  for (const op of ops) if (op.body) goType(op.body, `${upper(op.id)}Body`);

  const queries = [];
  const methods = [];
  for (const op of ops) {
    const O = upper(op.id);
    const args = ["ctx context.Context", ...op.pathParams.map((p) => `${p.replace(/Id$/, "ID")} string`)];
    if (op.body) args.push(`body *${O}Body`);
    if (op.query.length) {
      args.push(`params *${O}Params`);
      const fields = op.query.map((p) => {
        const doc = goDoc({ ...p.schema, description: p.description });
        return `${doc}\t${goName(p.name)} ${goType({ ...p.schema, format: undefined }, O + goName(p.name), !p.required)}`;
      });
      const sets = op.query.map((p) => `\tsetQuery(q, "${p.name}", p.${goName(p.name)})`);
      queries.push(
        `// ${O}Params are the query parameters of ${O}.\ntype ${O}Params struct {\n${fields.join("\n")}\n}\n\n` +
          `func (p *${O}Params) values() url.Values {\n\tq := url.Values{}\n\tif p == nil {\n\t\treturn q\n\t}\n${sets.join("\n")}\n\treturn q\n}\n`
      );
    }
    args.push("opts ...RequestOption");
    const ret = op.csv ? "[]byte" : op.response ? goType(op.response, `${O}Response`).replace(/^\*/, "") : "json.RawMessage";
    const path = op.pathParams.length
      ? `"${op.path.replace(/\{(\w+)\}/g, '" + url.PathEscape($1) + "').replace(/(\w+)Id\)/g, "$1ID)")}"`.replace(/ \+ ""$/, "")
      : `"${op.path}"`;
    const doc = docLines(op).flatMap((l) => l.split("\n")).map((l) => `// ${l}`.trimEnd());
    doc[0] = `// ${O} calls ${op.method} ${op.path}: ${op.summary}${op.summary.endsWith(".") ? "" : "."}`;
    methods.push(
      `${doc.join("\n")}\nfunc (c *Client) ${O}(${args.join(", ")}) (${op.csv ? "" : "*"}${ret}, error) {\n` +
        `\tvar out ${ret}\n` +
        `\tif err := c.do(ctx, "${op.method}", ${path}, ${op.query.length ? "params.values()" : "nil"}, ${op.body ? "body" : "nil"}, &out, opts); err != nil {\n\t\treturn nil, err\n\t}\n` +
        `\treturn ${op.csv ? "" : "&"}out, nil\n}\n`
    );
    if (op.paginated) {
      const item = goType(listItem(op.response), "");
      const pathArgs = op.pathParams.map((p) => p.replace(/Id$/, "ID"));
      methods.push(
        `// ${O}Iter iterates every item of ${O}, fetching pages as needed.\n` +
          `func (c *Client) ${O}Iter(${["ctx context.Context", ...pathArgs.map((p) => `${p} string`), `params *${O}Params`, "opts ...RequestOption"].join(", ")}) iter.Seq2[${item}, error] {\n` +
          `\tp := ${O}Params{}\n\tif params != nil {\n\t\tp = *params\n\t}\n` +
          `\treturn paginate(func(cursor *string) (*Page[${item}], error) {\n\t\tp.Cursor = cursor\n\t\treturn c.${O}(${["ctx", ...pathArgs, "&p", "opts..."].join(", ")})\n\t})\n}\n`
      );
    }
  }

  const out = [
    `// ${HEADER}`,
    "",
    "package pitchmentor",
    "",
    'import (\n\t"context"\n\t"encoding/json"\n\t"iter"\n\t"net/url"\n\t"time"\n)',
    "",
    "// WebhookEventTypes lists the events an endpoint can subscribe to.",
    `var WebhookEventTypes = []string{${subscribableEvents.map((e) => JSON.stringify(e)).join(", ")}}`,
    "",
    ...structs,
    ...queries,
    ...methods,
  ];
  const file = join(root, "generated.go");
  writeFileSync(file, out.join("\n"));
  execFileSync("gofmt", ["-w", file]);
}

genGo();
console.error(`generated ${ops.length} operations, ${Object.keys(schemas).length} schemas, ${webhookEvents.length} webhook events`);
